//! Differential corpus: the native applier must reach the state Source `Doc`
//! reached for the same seed and ops (generated by the ai-editing worker's
//! `native-corpus.test.ts`).
use crate::{EditorType, surface};
use lexical_model::*;
use serde_json::Value;
use std::collections::HashSet;

const TEXT_CORPUS: &str = include_str!("corpus/text.json");
const NEW_ID: &str = "<new>";

#[derive(serde::Deserialize)]
struct Entry {
    name: String,
    seed: Value,
    ops: Vec<Value>,
    state: Value,
    #[serde(rename = "failedAt")]
    failed_at: Option<usize>,
}

fn editor() -> Editor {
    // The host mints ids for split-off nodes; Source `Doc` does the same.
    crate::node_ids::NodeIdPlugin::register(
        surface::preset_builder_with_mode(EditorType::MarkdownSync, EditorMode::ViewAttached)
            .extension_state(crate::NodeClock(std::sync::Arc::new(|| 1234))),
        &["root", "paragraph", "text", "listitem", "task-list"],
        None,
        [3; 32],
    )
    .build()
    .expect("surface")
}

fn load(editor: &mut Editor, state: &Value) {
    let parsed = editor
        .parse_editor_state_str(&state.to_string())
        .expect("seed parses");
    editor
        .set_editor_state(parsed, TagSet::default())
        .expect("seed loads");
}

fn export(editor: &Editor) -> Value {
    serde_json::to_value(editor.state().to_json().expect("export")).expect("json")
}

fn collect_ids(value: &Value, ids: &mut HashSet<String>) {
    match value {
        Value::Array(items) => items.iter().for_each(|item| collect_ids(item, ids)),
        Value::Object(map) => {
            for (key, child) in map {
                if key == "$" {
                    if let Some(Value::String(id)) = child.get("id") {
                        ids.insert(id.clone());
                    }
                } else {
                    collect_ids(child, ids);
                }
            }
        }
        _ => {}
    }
}

/// Ids an op minted are random on both sides; seed ids must survive verbatim.
fn stable_ids(value: &Value, seed: &HashSet<String>) -> Value {
    match value {
        Value::Array(items) => Value::Array(items.iter().map(|v| stable_ids(v, seed)).collect()),
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(key, child)| {
                    if key == "$"
                        && let Value::Object(state) = child
                    {
                        let mut state = state.clone();
                        if let Some(Value::String(id)) = state.get("id")
                            && !seed.contains(id)
                        {
                            state.insert("id".into(), Value::String(NEW_ID.into()));
                        }
                        (key.clone(), Value::Object(state))
                    } else {
                        (key.clone(), stable_ids(child, seed))
                    }
                })
                .collect(),
        ),
        other => other.clone(),
    }
}

fn op_command(op: &Value, merge: bool) -> Command {
    surface::decode_command(
        "group-c.ai-op",
        &serde_json::json!({ "op": op, "merge": merge }).to_string(),
        0,
        None,
    )
    .expect("decodes")
    .expect("group-c.ai-op")
}

/// Apply like the host: in order, merging after the first, stopping at a refusal.
fn replay(editor: &mut Editor, ops: &[Value]) -> Option<usize> {
    for (index, op) in ops.iter().enumerate() {
        let (handled, _) = editor
            .dispatch(&op_command(op, index > 0))
            .expect("dispatch");
        if handled == Handled::No {
            return Some(index);
        }
    }
    None
}

#[test]
fn text_ops_reach_the_source_doc_state() {
    let corpus: Vec<Entry> = serde_json::from_str(TEXT_CORPUS).expect("corpus");
    assert!(!corpus.is_empty());
    let mut failures = Vec::new();
    for entry in corpus {
        let mut seed_ids = HashSet::new();
        collect_ids(&entry.seed, &mut seed_ids);

        let mut native = editor();
        load(&mut native, &entry.seed);
        let failed_at = replay(&mut native, &entry.ops);
        let actual = stable_ids(&export(&native), &seed_ids);

        // Compare against Source's result as the native model represents it.
        let mut source = editor();
        load(&mut source, &entry.state);
        let expected = stable_ids(&export(&source), &seed_ids);

        if failed_at != entry.failed_at || actual != expected {
            failures.push(format!(
                "{}: failedAt native {failed_at:?} source {:?}\n  native {actual}\n  source {expected}",
                entry.name, entry.failed_at
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn an_unknown_op_kind_is_refused_without_changing_the_document() {
    let corpus: Vec<Entry> = serde_json::from_str(TEXT_CORPUS).expect("corpus");
    let entry = &corpus[0];
    let mut native = editor();
    load(&mut native, &entry.seed);
    let before = export(&native);
    let op = serde_json::json!({ "kind": "notAnOp", "node": "s0000001" });
    assert_eq!(
        native
            .dispatch(&op_command(&op, false))
            .expect("dispatch")
            .0,
        Handled::No
    );
    assert_eq!(export(&native), before);
}

#[test]
fn selected_block_ids_are_the_touched_top_level_blocks_in_order() {
    let corpus: Vec<Entry> = serde_json::from_str(TEXT_CORPUS).expect("corpus");
    let entry = corpus
        .iter()
        .find(|entry| entry.name == "setText on each of two blocks")
        .expect("two-block seed");
    let mut native = editor();
    load(&mut native, &entry.seed);
    let blocks: Vec<NodeKey> = native.state().view().children(NodeKey::ROOT).collect();
    let texts: Vec<NodeKey> = blocks
        .iter()
        .filter_map(|block| native.state().view().first_child(*block))
        .collect();
    let ids = |editor: &Editor| {
        surface::query(
            "group-c.selected-block-ids",
            &Value::Null,
            0,
            editor.state(),
        )
        .expect("query")
        .expect("registered query")
    };
    // No range selection: Source resolves nothing.
    assert_eq!(ids(&native), serde_json::json!([]));
    native
        .update(|tx| {
            tx.set_selection(Some(Selection::Range(RangeSelection::new(
                Point::text(texts[0], Utf16Offset(2)),
                Point::text(texts[1], Utf16Offset(3)),
            ))))?;
            Ok(())
        })
        .expect("select across both blocks");
    let expected: Vec<Value> = entry
        .ops
        .iter()
        .map(|op| op.get("node").cloned().expect("op node"))
        .collect();
    assert_eq!(ids(&native), Value::Array(expected));
}
